/**
 * Normalize callback payload (JSON-only).
 */
const j = $json || {};
const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');

const orderId = pick(j.orderId, null);
const characterHash = pick(j.characterHash, null);
const poseNumberRaw = pick(j.poseNumber, null);
const poseNumber = (poseNumberRaw === 0 || poseNumberRaw === '0') ? 0 : Number(poseNumberRaw);

if (!orderId) throw new Error('2B callback: orderId required');
if (!characterHash) throw new Error('2B callback: characterHash required');
if (!Number.isFinite(poseNumber)) throw new Error('2B callback: poseNumber required');

const backendUrl = pick(j.backendUrl, 'https://admin.littleherolabs.com');
const manifest2aUrl = pick(j.manifest2aUrl, `${backendUrl}/api/manifests/book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2a-manifest.json`);

const result = {
  orderId, characterHash, poseNumber,
  approvedKey: pick(j.approvedKey, null),
  sourceReplacedAt: pick(j.sourceReplacedAt, null),
  sourceReplacementCount: Number(pick(j.sourceReplacementCount, 0) || 0),
  sourceUrl: pick(j.sourceUrl, null),
  briaStatus: pick(j.briaStatus, 'error'),
  briaRequestId: pick(j.briaRequestId, null),
  briaStatusUrl: pick(j.briaStatusUrl, null),
  briaCompletedAt: pick(j.briaCompletedAt, null),
  briaErrorMessage: pick(j.briaErrorMessage, null),
  bgRemovedKey: pick(j.bgRemovedKey, null),
  bgRemovedContentType: pick(j.bgRemovedContentType, null),
  bgRemovedSizeBytes: (j.bgRemovedSizeBytes === 0 ? 0 : (Number(j.bgRemovedSizeBytes) || null)),
  bgRemovedImageUrl: pick(j.bgRemovedImageUrl, null),
  qa: (j.qa && typeof j.qa === 'object') ? j.qa : null,
  needsReview: !!pick(j.needsReview, false),
  reviewReason: pick(j.reviewReason, null),
};

const manifest2bKey = `book-mvp-simple-adventure/orders/${String(orderId)}/manifests/2b-manifest.json`;

return [{ json: { backendUrl, manifest2aUrl, manifest2bKey, result } }];

/**
 * Merge the incoming pose result into 2B manifest (create if missing).
 */
let ctx = {};
try { ctx = $items('Normalize Callback', 0, $runIndex)?.[0]?.json || {}; } catch {}
const incoming = ctx.result;

const manifest2bMaybe = $items('Download 2B Manifest (if exists)', 0, $runIndex)?.[0]?.json || null;
const manifest2a = $items('Download 2A Manifest', 0, $runIndex)?.[0]?.json || null;
if (!manifest2a?.schema) throw new Error('2B callback: missing 2A manifest');

// Detect 2B manifest existence: backend returns JSON error on 404; treat as missing if no schema
let manifest2b = (manifest2bMaybe && manifest2bMaybe.schema === 'lhb.run-manifest@v2.0') ? manifest2bMaybe : null;

if (!manifest2b) {
  // Create skeleton 2B manifest from 2A
  manifest2b = JSON.parse(JSON.stringify(manifest2a));
  manifest2b.stage = '2b';
  manifest2b.createdAt = new Date().toISOString();
  manifest2b.updatedAt = new Date().toISOString();
  (manifest2b.entries || []).forEach(e => {
    e.bgRemovedKey = null;
    e.bgRemovedImageUrl = null;
    e.briaStatus = null;
    e.briaRequestId = null;
    e.briaStatusUrl = null;
    e.briaErrorMessage = null;
    e.sourceApprovedKey = null;
    e.sourceReplacedAt = null;
    e.sourceReplacementCount = 0;
    e.processedAt = null;
  });
}

// Update pose entry
const poseNumber = Number(incoming.poseNumber);
const entry = (manifest2b.entries || []).find(e => Number(e.poseNumber) === poseNumber);
if (!entry) throw new Error(`2B callback: pose ${poseNumber} not found in manifest entries`);

entry.sourceApprovedKey = incoming.approvedKey || entry.approvedKey || null;
entry.sourceReplacedAt = incoming.sourceReplacedAt || null;
entry.sourceReplacementCount = Number(incoming.sourceReplacementCount || 0);
entry.processedAt = new Date().toISOString();

entry.briaStatus = incoming.briaStatus;
entry.briaRequestId = incoming.briaRequestId || null;
entry.briaStatusUrl = incoming.briaStatusUrl || null;
entry.briaErrorMessage = incoming.briaErrorMessage || null;

// QA
if (incoming.qa && typeof incoming.qa === 'object') {
  entry.qa = { ...(entry.qa || {}), ...incoming.qa };
}

if (incoming.briaStatus === 'completed') {
  entry.bgRemovedKey = incoming.bgRemovedKey || entry.bgRemovedKey;
  entry.bgRemovedImageUrl = incoming.bgRemovedImageUrl || entry.bgRemovedImageUrl;
  entry.bgRemovedStatus = 'completed';
  entry.bgRemoved = true;
  entry.needsReview = incoming.needsReview === true;
  entry.reviewReason = incoming.needsReview === true ? (incoming.reviewReason || 'transparency_fail_or_low_conf') : null;
} else {
  entry.bgRemoved = false;
  entry.bgRemovedStatus = incoming.briaStatus;
  entry.needsReview = true;
  entry.reviewReason = incoming.reviewReason || 'unknown';
}

manifest2b.updatedAt = new Date().toISOString();

// Completion check: all approved poses are terminal
const approved2a = (manifest2a.entries || []).filter(e => e?.approved && e?.status === 'approved');
const approvedCount = approved2a.length;

const isTerminal = (s) => ['completed','failed','timeout','error'].includes(String(s||'').toLowerCase());
const approvedNums = new Set(approved2a.map(e => Number(e.poseNumber)));
const terminalApproved = (manifest2b.entries || []).filter(e => approvedNums.has(Number(e.poseNumber)) && isTerminal(e.briaStatus)).length;
const complete = (approvedCount > 0) && (terminalApproved === approvedCount);

// Order-level review flags
const approvedEntries2b = (manifest2b.entries || []).filter(e => approvedNums.has(Number(e.poseNumber)));
const needsHumanReview = approvedEntries2b.some(e => e.needsReview === true || e.needs_review === true);
const allSucceeded = approvedEntries2b.every(e => String(e.briaStatus||'').toLowerCase() === 'completed');
const readyForBook = allSucceeded && !needsHumanReview;

// Minimal summary
manifest2b.summary = manifest2b.summary || {};
manifest2b.summary.approvedPoseCount = approvedCount;
manifest2b.summary.terminalPoseCount = terminalApproved;
manifest2b.summary.complete = complete;
manifest2b.summary.needsHumanReview = needsHumanReview;
manifest2b.summary.readyForBook = readyForBook;

return [{ json: { manifest2b, complete, manifest2bKey: ctx.manifest2bKey, backendUrl: ctx.backendUrl } }];

/**
 * Create binary for S3 upload (manifest JSON).
 */
const manifest = $json.manifest2b;
const s = JSON.stringify(manifest, null, 2);
const b64 = Buffer.from(s, 'utf8').toString('base64');

return [{
  json: { manifest2bKey: $json.manifest2bKey, complete: $json.complete, backendUrl: $json.backendUrl },
  binary: {
    data: {
      data: b64,
      mimeType: 'application/json',
      fileName: '2b-manifest.json'
    }
  }
}];
